exitEff_eq 
  OLD {s : S3} {f : Nat} {F₀ : Frames} (hF : s.F = f :: F₀) : exitEff s = { s with F := F₀ D := fun q => (s.D q).map (reanchor s f) A := s.A.map (exitG s f) } 
  NEW {s : S3} {f : Nat} {F₀ : Frames} (hF : s.F = f :: F₀) : exitEff s = { s with F := F₀ D := fun q => (s.D q).map fun x => (firstSurv s F₀ (x :: s.ancs x)).getD x A := mapI (exitG s F₀) 0 s.A }
